using System.Text.Json.Nodes;
using Campfire.Application.Storage;

namespace Campfire.Application.Tests.Storage.Support;

/// <summary>
/// <c>vectors/storage.json</c> and <c>vectors/storage/</c>, generated by
/// <c>reference-tools/storage/generate.rb</c> inside the reference image (never edited by hand), and
/// the Rails fixtures they were made from.
/// </summary>
internal static class StorageVectors
{
    private static readonly Lazy<JsonObject> Document = new( ( ) => RepositoryPaths.ReadVectorJson( "storage.json" ).AsObject( ) );
    private static readonly Lazy<ActiveStorageVerifier> VectorVerifier = new( CreateVerifier );

    public static JsonObject All => Document.Value;

    /// <summary>The generator's frozen clock (<c>2026-09-26T12:00:00Z</c>), before any vector expires.</summary>
    public static DateTimeOffset Now { get; } = new( 2026, 9, 26, 12, 0, 0, TimeSpan.Zero );

    /// <summary>The Active Storage verifier for the parity <c>SECRET_KEY_BASE</c> the vectors were signed with.</summary>
    public static ActiveStorageVerifier Verifier => VectorVerifier.Value;

    /// <summary>A Rails test fixture file (<c>test/fixtures/files</c>); fails clearly when the Rails app isn't available.</summary>
    public static string Fixture( string name )
    {
        var path = RepositoryPaths.ReferencePath( "test", "fixtures", "files", name );
        Assert.True( File.Exists( path ), $"The Rails fixture {path} is missing." );

        return path;
    }

    /// <summary>A processed file the generator saved under <c>vectors/storage/</c>.</summary>
    public static string SavedFile( string name ) => RepositoryPaths.VectorPath( "storage", name );

    /// <summary>The array at <paramref name="name"/>; fails when it is missing or empty.</summary>
    public static IReadOnlyList<JsonObject> Cases( string name )
    {
        var cases = All[name] as JsonArray ?? throw new InvalidDataException( $"storage.json has no {name} array." );
        Assert.NotEmpty( cases );

        return [.. cases.Select( item => item!.AsObject( ) )];
    }

    /// <summary>
    /// A Ruby value as the generator types it: <c>{"sym": "webp"}</c>, <c>{"str": "jpg"}</c>,
    /// <c>{"hash": [[key, value], ...]}</c>, arrays, integers, booleans and <c>null</c>.
    /// </summary>
    public static JsonNode? Typed( JsonNode? node ) => node switch
    {
        null => null,
        JsonArray items => new JsonArray( items.Select( Typed ).ToArray( ) ),
        JsonObject tagged when tagged["sym"] is { } symbol => JsonValue.Create( symbol.RequiredString( ) ),
        JsonObject tagged when tagged["str"] is { } text => JsonValue.Create( text.RequiredString( ) ),
        JsonObject tagged when tagged["hash"] is JsonArray pairs =>
            new JsonObject( pairs.Select( pair => new KeyValuePair<string, JsonNode?>( pair![0].RequiredString( ), Typed( pair[1] ) ) ) ),
        JsonValue value => value.DeepClone( ),
        _ => throw new InvalidDataException( $"Untyped vector value {node.ToJsonString( )}." ),
    };

    public static Variation TypedVariation( JsonNode? node ) => new( Assert.IsType<JsonObject>( Typed( node ) ) );

    /// <summary>A blob row as the generator recorded it.</summary>
    public static Blob BlobRow( JsonNode? row ) => new( )
    {
        Id = row!["id"].RequiredLong( ),
        Key = row["key"].RequiredString( ),
        Filename = new BlobFilename( row["filename"].RequiredString( ) ),
        ContentType = row["content_type"].OptionalString( ),
        Metadata = BlobMetadata.Parse( row["metadata"].OptionalString( ) ),
        ServiceName = row["service_name"].RequiredString( ),
        ByteSize = row["byte_size"].RequiredLong( ),
        Checksum = row["checksum"].OptionalString( ),
    };

    private static ActiveStorageVerifier CreateVerifier( )
    {
        return new ActiveStorageVerifier( new TestTokenProtector( ) );
    }
}
